    "multi-agent-simulation-markdown-code-2": "v_new = v + alpha × (v_avg - v)\np_new = p + v_new",
    "multi-agent-simulation-markdown-code-3": "N = 2\nagents = [\n  0.0, 0.0, 1.0,  0.0,\n  3.0, 4.0, 0.0, -1.0\n]",
    "multi-agent-simulation-markdown-code-4": "agents_next = [\n  1.0,  0.0, 1.0,  0.0,\n  3.0,  3.0, 0.0, -1.0\n]",
    "multi-agent-simulation-markdown-code-5": "#include <cuda_runtime.h>\n\n// agents, agents_next are device pointers\nextern \"C\" void solve(\n    const float* agents,\n    float* agents_next,\n    int N\n) {}",
    "multi-agent-simulation-markdown-code-6": "dx² + dy² < 25",
